def verify_native_file(file, source=None):
    file=Path(file)
    rel=file.parent.name+'/'+file.name
    if rel not in EXPECTED:
        raise AssertionError(('unreviewed native source',rel))
    text=source if source is not None else file.read_text(encoding='utf8')
    methods={n.name:n for n in ast.parse(text).body if isinstance(n,ast.FunctionDef)}
    for name,expected in EXPECTED[rel].items():
        node=methods.get(name)
        if node is None or sha256(ast.dump(node,include_attributes=False).encode()).hexdigest()!=expected:
            raise AssertionError(('native source method has changed',rel,name))
    return len(EXPECTED[rel])
